def news2_score(resp_rate: int, spo2: int, on_oxygen: bool, sbp: int, pulse: int, alert: bool, temp_c: float) -> int:
    """
    Return the National Early Warning Score 2 (SpO2 scale 1).

    Respiration rate: <= 8 -> 3, 9-11 -> 1, 12-20 -> 0, 21-24 -> 2, >= 25 -> 3.
    SpO2 (%): <= 91 -> 3, 92-93 -> 2, 94-95 -> 1, >= 96 -> 0.
    Supplemental oxygen: 2, room air: 0.
    Systolic BP: <= 90 -> 3, 91-100 -> 2, 101-110 -> 1, 111-219 -> 0, >= 220 -> 3.
    Pulse: <= 40 -> 3, 41-50 -> 1, 51-90 -> 0, 91-110 -> 1, 111-130 -> 2, >= 131 -> 3.
    Consciousness: alert 0, otherwise (new confusion, voice, pain, unresponsive) 3.
    Temperature (C): <= 35.0 -> 3, 35.1-36.0 -> 1, 36.1-38.0 -> 0, 38.1-39.0 -> 1,
    >= 39.1 -> 2.

    Examples:
    >>> news2_score(18, 97, False, 125, 75, True, 37.0)
    0
    >>> news2_score(26, 90, True, 88, 135, False, 39.5)
    19
    """
    s = 0
    if resp_rate <= 8:
        s += 3
    elif resp_rate <= 11:
        s += 1
    elif resp_rate <= 20:
        s += 0
    elif resp_rate <= 24:
        s += 2
    else:
        s += 3
    if spo2 <= 91:
        s += 3
    elif spo2 <= 93:
        s += 2
    elif spo2 <= 95:
        s += 1
    if on_oxygen:
        s += 2
    if sbp <= 90:
        s += 3
    elif sbp <= 100:
        s += 2
    elif sbp <= 110:
        s += 1
    elif sbp >= 220:
        s += 3
    if pulse <= 40:
        s += 3
    elif pulse <= 50:
        s += 1
    elif pulse <= 90:
        s += 0
    elif pulse <= 110:
        s += 1
    elif pulse <= 130:
        s += 2
    else:
        s += 3
    if not alert:
        s += 3
    if temp_c <= 35.0:
        s += 3
    elif temp_c <= 36.0:
        s += 1
    elif temp_c <= 38.0:
        s += 0
    elif temp_c <= 39.0:
        s += 1
    else:
        s += 2
    return s

